// Gap Analysis. Reuses probe data; writes gaps atomically via the
// recompute_visibility_gaps() RPC (one transaction — a mid-run failure never
// empties the table). A gap needs normalized competitor-DOMAIN evidence, not a
// bare name substring. Only SUCCESSFUL (ok) latest checks are considered.
const SB_URL = $env.SUPABASE_URL;
const SB_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const http = this.helpers.httpRequest;
if (!SB_URL || !SB_KEY) return [{ json: { skipped: true, reason: 'SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY not set' } }];

function rest(path, opts) {
  opts = opts || {};
  return http(Object.assign({ url: SB_URL + '/rest/v1/' + path, json: true }, opts, {
    headers: Object.assign({ apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' }, opts.headers || {}),
  }));
}
function normDomain(d) { if (!d) return ''; return String(d).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').trim(); }
function hostOf(u) { try { return normDomain(new URL(u).host); } catch (e) { return normDomain(u); } }
function urlMatchesDomain(u, dom) { if (!u || !dom) return false; const h = hostOf(u); return h === dom || h.endsWith('.' + dom); }
function textIncludes(t, n) { if (!t || !n) return false; return String(t).toLowerCase().includes(String(n).toLowerCase()); }

const queries = await rest('target_queries?select=id,query_text,entity_id&active=eq.true');
const competitors = await rest('competitors?select=id,entity_id,name,domain');
const checks = await rest('visibility_checks?select=query_id,platform,mentioned,ok,run_at,snippet,source_urls&order=run_at.desc');

const compByEntity = {};
for (const c of competitors) (compByEntity[c.entity_id] = compByEntity[c.entity_id] || []).push(c);

// latest SUCCESSFUL check per (query, platform) — checks are newest-first.
const latest = {};
for (const ch of checks) {
  if (ch.ok === false) continue; // ignore failed/skipped probes
  const k = ch.query_id + '\u0000' + ch.platform;
  if (!latest[k]) latest[k] = ch;
}

const gaps = [];
const seen = {};
for (const q of queries) {
  const comps = compByEntity[q.entity_id] || [];
  if (comps.length === 0) continue;
  for (const key of Object.keys(latest)) {
    const ch = latest[key];
    if (ch.query_id !== q.id) continue;
    if (ch.mentioned !== false) continue;
    const urls = Array.isArray(ch.source_urls) ? ch.source_urls : [];
    const snippet = ch.snippet || '';
    for (const comp of comps) {
      const dom = normDomain(comp.domain);
      if (!dom) continue;
      const inUrls = urls.some(function (u) { return urlMatchesDomain(u, dom); });
      const inSnippet = textIncludes(snippet, dom); // DOMAIN evidence only, not the bare name
      if (!inUrls && !inSnippet) continue;
      const dedup = q.id + '|' + ch.platform + '|' + comp.id;
      if (seen[dedup]) continue;
      seen[dedup] = true;
      const where = inUrls ? 'cited in sources' : 'domain named in the answer';
      gaps.push({
        query_id: q.id,
        platform: ch.platform,
        competitor_id: comp.id,
        note: comp.name + ' (' + dom + ') ' + where + ' for "' + q.query_text + '" on ' + ch.platform + '; we are not mentioned',
      });
    }
  }
}

// Atomic replace of the whole snapshot (RPC runs in one transaction).
const n = await rest('rpc/recompute_visibility_gaps', { method: 'POST', body: { gaps: gaps } });
return [{ json: { gaps_written: gaps.length, rpc_result: n } }];
